 [("For", "Short-term insomnia"),
  ("Works", "Falls asleep somewhat faster, sleeps a little longer"),
  ("Cost", "Mostly private scripts, around $15 to $30"),
  ("Kicks in", "15 to 30 minutes"),
  ("Dose", "Zolpidem 10 mg (5 mg in older adults) right at bedtime; zopiclone 3.75 to 7.5 mg"),
  ("Watch for", "Sleepwalking or other sleep behaviours, next-day drowsiness, bitter taste (zopiclone)")],
 "Short term only, and in bed when you take it.",
 ["Zolpidem: Stilnox, Stilnox CR, Dormizol. Zopiclone: Imovane, Imrest"],
 "Z-drugs act on the same GABA receptors as benzodiazepines, but more selectively.",
 ["Short-term insomnia (up to 4 weeks)", "Occasional use, e.g. during a crisis or shift changes, under medical advice"],
 "Most effects relate to sedation lasting too long or acting at the wrong time.",
 [g(C, ["Next-day drowsiness", "Headache", "Dizziness", "Bitter metallic taste (zopiclone)"]), g(U, ["<b>Complex sleep behaviours</b>: sleepwalking, sleep-eating, sleep-driving, with no memory", "Memory lapses", "Falls"]), g(R, ["Hallucinations", "Dependence and rebound insomnia"])],
 ["Any sleepwalking, sleep-driving or other complex behaviour: stop and tell your doctor", "Breathing problems, especially with sleep apnoea"],
 ["Take it only when in bed with 7 to 8 hours available.", "No alcohol or other sedatives.", "Don’t drive the next morning if at all drowsy.", "Ask about CBT for insomnia, which works better long term."],
 [("Is Stilnox addictive?", "It can cause dependence and rebound insomnia, especially with nightly use beyond a few weeks."),
  ("What are the side effects of zolpidem?", "Drowsiness, dizziness and headache are common. Complex sleep behaviours like sleepwalking or sleep-driving are less common but serious."),
  ("What works better than sleeping pills?", "CBT for insomnia (CBT-I) is the recommended first-line treatment and keeps working after it ends.")],
 [("Sleep Health Foundation", "https://www.sleephealthfoundation.org.au/"), ("PBS: Zolpidem", PBS + "zolpidem")],
