 "Usually well tolerated; nausea is the commonest early issue.",
 [g(C, ["Nausea", "Headache", "Dizziness", "Tiredness", "Trouble sleeping"]), g(U, ["Raised liver enzymes", "Low mood"]), g(R, ["<b>Sudden opioid withdrawal</b> if taken while using opioids", "<b>Overdose risk</b> if using opioids after stopping (lost tolerance)"])],
